QUESTIONS = []
for i, (topic, question, correct, d1, d2, d3, why) in enumerate(ROWS):
    choices = [correct, d1, d2, d3]
    order = list(range(4))
    random.Random(i + 1947).shuffle(order)
    QUESTIONS.append({'topic':topic,'q':question,'a':[choices[n] for n in order], 'correct':order.index(0), 'why':why})
